        "013e952763c94f61a4c096f31ef50dc3": {
          "id": "013e952763c94f61a4c096f31ef50dc3",
          "stepType": "ScriptOutput",
          "name": "hr cases retrieve ",
          "output_type": "single_part",
          "script": "(function execute() {\n\n    var gr = new GlideRecord('x_snc_unified_hr_0_hr_case');\n\n    // Find cases assigned to the currently logged-in HR agent\n    gr.addQuery('assigned_to', gs.getUserID());\n    gr.orderByDesc('sys_created_on');\n    gr.query();\n\n    var response = '';\n    var count = 0;\n\n    while (gr.next()) {\n\n        count++;\n\n        response += count + '. ' +\n            gr.getDisplayValue('number') +\n            ' - ' +\n            gr.getDisplayValue('category') +\n            ' - ' +\n            gr.getDisplayValue('priority') +\n            ' - ' +\n            gr.getDisplayValue('status') +\n            '\\n';\n    }\n\n    if (count == 0) {\n        return 'You currently have no HR cases assigned to you.';\n    }\n\n    return 'You have ' + count + ' HR case(s) assigned to you.\\n\\n' +\n           response;\n\n})()",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
        "5b5e01b63cb64c389f02f385707d63b2": {
          "id": "5b5e01b63cb64c389f02f385707d63b2",
          "stepType": "ScriptOutput",
          "name": "Case Attention Insights",
          "output_type": "single_part",
          "script": "(function execute() {\n\n    var gr = new GlideRecord('x_snc_unified_hr_0_hr_case');\n\n    gr.addQuery('assigned_to', gs.getUserID());\n    gr.query();\n\n    var total = 0;\n    var highPriority = 0;\n    var openCases = 0;\n    var inProgressCases = 0;\n    var attentionCases = '';\n\n    while (gr.next()) {\n\n        total++;\n\n        var priority = gr.getDisplayValue('priority');\n        var status = gr.getDisplayValue('status');\n\n        if (priority == 'High'&&status!='Resolved') {\n            highPriority++;\n        }\n\n        if (status == 'Open') {\n            openCases++;\n        }\n\n        if (status == 'In Progress') {\n            inProgressCases++;\n        }\n\n        // Cases requiring attention\n        if ((priority == 'High' && status != 'Resolved') || status == 'Open')  {\n\n            attentionCases +=\n                gr.getDisplayValue('number') +\n                ' - ' +\n                gr.getDisplayValue('priority') +\n                ' - ' +\n                gr.getDisplayValue('status') +\n                ' - ' +\n                gr.getDisplayValue('category') +\n                '\\n';\n        }\n    }\n\n    if (total == 0) {\n        return 'You currently have no cases assigned to you.';\n    }\n\n    var response = '';\n\n    response += 'YOUR CASE WORKLOAD\\n\\n';\n\n    response += 'Total Assigned: ' + total + '\\n';\n    response += 'High Priority: ' + highPriority + '\\n';\n    response += 'Open: ' + openCases + '\\n';\n    response += 'In Progress: ' + inProgressCases + '\\n';\n\n    if (attentionCases != '') {\n\n        response += '\\nCASES REQUIRING ATTENTION\\n\\n';\n        response += attentionCases;\n\n    } else {\n\n        response += '\\nNo cases currently require special attention.';\n    }\n\n    return response;\n\n})()",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
